-- Rank the bounded cross-month weekend/night load after required coverage and hours.
create or replace function private.sf_autonomy_rank(summary_ jsonb,result_ jsonb) returns numeric[] language sql immutable set search_path='' as $$
 select array[case when coalesce((summary_->>'canApply')::boolean,false) then 0 else 1 end,coalesce((summary_->>'errors')::numeric,1e9),coalesce((summary_->>'critical')::numeric,1e9),coalesce((summary_->>'open')::numeric,1e9),greatest(0,coalesce((summary_->>'spread')::numeric,1e9)-coalesce((summary_->>'maximumShift')::numeric,0)),coalesce((summary_#>>'{quality,priorityDeficit}')::numeric,(select sum(coalesce((q->>'priorityDeficit')::numeric,0)) from jsonb_array_elements(coalesce(result_->'quality','[]')) q),0),coalesce((summary_#>>'{quality,teamLeaderDeficit}')::numeric,(select sum(coalesce((q->>'teamLeaderDeficit')::numeric,0)) from jsonb_array_elements(coalesce(result_->'quality','[]')) q),0),coalesce((summary_#>>'{quality,deficit}')::numeric,(select sum(coalesce((q->>'deficit')::numeric,0)) from jsonb_array_elements(coalesce(result_->'quality','[]')) q),0),coalesce((summary_#>>'{quality,imbalance}')::numeric,(select sum(coalesce((q->>'imbalance')::numeric,(q->>'squared')::numeric,0)) from jsonb_array_elements(coalesce(result_->'quality','[]')) q),0),coalesce((summary_#>>'{quality,burdenPenalty}')::numeric,(select sum(coalesce((q->>'burdenPenalty')::numeric,0)) from jsonb_array_elements(coalesce(result_->'quality','[]')) q),0),coalesce((summary_#>>'{continuity,total}')::numeric,0)]::numeric[]
$$;
revoke all on function private.sf_autonomy_rank(jsonb,jsonb) from public,anon,authenticated;
